package com.example.bank_system.domain.util;

import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;
import java.util.Arrays;

import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

/**
 * PIN key-derivation and verification utilities.
 *
 * Security posture (from Phase 3 §9.2):
 *  - 16-byte salt generated by SecureRandom.
 *  - PBKDF2WithHmacSHA256, 200,000 iterations, 256-bit output.
 *  - Raw PIN char[] and derived key bytes are zeroed immediately after use.
 *  - Comparison uses a constant-time-style check (MessageDigest.isEqual equivalent).
 *  - This protects against casual access on a lost phone; it does NOT encrypt
 *    the SQLite database or provide production banking security.
 *
 * All methods are pure Java — no Android dependencies — so they are testable
 * with plain JUnit without an emulator.
 */
public final class PinKdf {

    public static final String ALGORITHM  = "PBKDF2WithHmacSHA256";
    public static final int    ITERATIONS = 200_000;
    public static final int    KEY_BITS   = 256;
    public static final int    SALT_BYTES = 16;

    // PIN length constraints (6–12 numeric digits).
    public static final int MIN_PIN_LENGTH = 6;
    public static final int MAX_PIN_LENGTH = 12;

    private PinKdf() { }

    // -------------------------------------------------------------------------
    // Salt generation
    // -------------------------------------------------------------------------

    /** Generates a fresh cryptographically random 16-byte salt. */
    public static byte[] generateSalt() {
        byte[] salt = new byte[SALT_BYTES];
        new SecureRandom().nextBytes(salt);
        return salt;
    }

    // -------------------------------------------------------------------------
    // Hashing
    // -------------------------------------------------------------------------

    /**
     * Derives a 256-bit verifier from the given PIN and salt.
     *
     * @param pin  The numeric PIN as a char array. Caller should zero it after use.
     * @param salt A fresh 16-byte (or longer) salt from {@link #generateSalt()}.
     * @return The raw verifier bytes (32 bytes).
     * @throws IllegalStateException if PBKDF2WithHmacSHA256 is unavailable on this device.
     */
    public static byte[] deriveVerifier(char[] pin, byte[] salt) {
        PBEKeySpec spec = null;
        try {
            spec = new PBEKeySpec(pin, salt, ITERATIONS, KEY_BITS);
            SecretKeyFactory factory = SecretKeyFactory.getInstance(ALGORITHM);
            return factory.generateSecret(spec).getEncoded();
        } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
            throw new IllegalStateException("PBKDF2WithHmacSHA256 unavailable on this device", e);
        } finally {
            if (spec != null) {
                spec.clearPassword();
            }
        }
    }

    // -------------------------------------------------------------------------
    // Verification
    // -------------------------------------------------------------------------

    /**
     * Returns true if the supplied PIN matches the stored verifier.
     *
     * Uses a constant-length comparison to avoid timing side-channels
     * (equivalent to MessageDigest.isEqual on Android).
     *
     * @param candidatePin  The PIN entered by the user. Zeroed internally after derivation.
     * @param salt          The salt stored in auth_state.
     * @param storedVerifier The verifier bytes stored in auth_state.
     * @return true if the PIN is correct.
     */
    public static boolean verify(char[] candidatePin, byte[] salt, byte[] storedVerifier) {
        byte[] derived = null;
        try {
            derived = deriveVerifier(candidatePin, salt);
            return constantTimeEquals(derived, storedVerifier);
        } finally {
            if (derived != null) {
                Arrays.fill(derived, (byte) 0);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Input validation
    // -------------------------------------------------------------------------

    /**
     * Returns true if the PIN is 6–12 characters of ASCII digits only.
     * Never log the PIN value.
     */
    public static boolean isValidPin(char[] pin) {
        if (pin == null) return false;
        if (pin.length < MIN_PIN_LENGTH || pin.length > MAX_PIN_LENGTH) return false;
        for (char c : pin) {
            if (c < '0' || c > '9') return false;
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    /**
     * Constant-time byte array comparison.
     * Returns true only if both arrays are the same length and every byte matches.
     */
    static boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int diff = 0;
        for (int i = 0; i < a.length; i++) {
            diff |= (a[i] ^ b[i]);
        }
        return diff == 0;
    }
}
